css:
@page { size: A4 landscape; margin: 0; }
html, body { margin: 0; padding: 0; background: #ffffff; direction: ltr; }
.print-format { orientation: landscape; page-size: A4; margin-top: 0mm; margin-bottom: 0mm; margin-left: 0mm; margin-right: 0mm; }
.print-format-gutter, .print-format { direction: ltr !important; margin: 0 !important; padding: 0 !important; width: auto !important; max-width: none !important; min-height: 0 !important; border: 0 !important; box-shadow: none !important; background: #ffffff !important; }
.action-banner { display: none !important; }
.cf-cert { position: relative; width: 1122px; height: 793px; overflow: hidden; background: #ffffff; color: #171717; line-height: 1.3; font-size: 16px; text-align: left; text-rendering: auto; -webkit-print-color-adjust: exact; print-color-adjust: exact; page-break-inside: avoid; }
.cf-cert[dir="rtl"] { text-align: right; }
.cf-cert, .cf-cert * { box-sizing: border-box; }
.cf-cert .cf-t { display: table; border-collapse: collapse; width: 100%; }
.cf-cert .cf-tr { display: table-row; }
.cf-cert .cf-td { display: table-cell; vertical-align: top; }
.cf-cert-sans { font-family: "LMS Sans", "LMS Sans Arabic", sans-serif; }
.cf-cert-serif { font-family: "LMS Serif", "LMS Naskh Arabic", serif; }
.cf-cert .cf-mono { font-family: "LMS Mono", monospace; }
.cf-cert .cf-ltr { direction: ltr; unicode-bidi: embed; }
.cf-cert .cf-muted { color: #525252; }
.cf-cert .cf-soft { color: #383838; }
.cf-cert .cf-bold { font-weight: 700; }
.cf-cert .cf-wrap, .cf-cert .cf-verify { word-wrap: break-word; }
.cf-cert .cf-start { text-align: left; }
.cf-cert .cf-end { text-align: right; }
.cf-cert .cf-center { text-align: center; }
.cf-cert[dir="rtl"] .cf-start { text-align: right; }
.cf-cert[dir="rtl"] .cf-end { text-align: left; }
.cf-cert .cf-middle { vertical-align: middle; }
.cf-cert .cf-bottom { vertical-align: bottom; }
html body .print-format .cf-cert img { width: auto !important; max-width: none !important; max-height: none !important; border: 0; }
.cf-cert .cf-logo { display: block; height: 44px; width: auto; }
.cf-cert .cf-qr { display: block; }
.cf-cert .cf-label { font-size: 13px; color: #525252; }
.cf-cert .cf-value { margin-top: 3px; }
.cf-cert .cf-tight { letter-spacing: -0.02em; }
.cf-cert[dir="rtl"] .cf-tight { letter-spacing: normal; }
.cf-cert-corners .cf-mark { position: absolute; width: 56px; height: 56px; border: 0 solid #171717; }
.cf-cert-corners .cf-mark-top-left { top: 36px; left: 36px; border-top-width: 3px; border-left-width: 3px; }
.cf-cert-corners .cf-mark-top-right { top: 36px; right: 36px; border-top-width: 3px; border-right-width: 3px; }
.cf-cert-corners .cf-mark-bottom-left { bottom: 36px; left: 36px; border-bottom-width: 3px; border-left-width: 3px; }
.cf-cert-corners .cf-mark-bottom-right { bottom: 36px; right: 36px; border-bottom-width: 3px; border-right-width: 3px; }
.cf-cert-corners .cf-body { position: absolute; top: 64px; left: 104px; right: 104px; bottom: 60px; }
.cf-cert-corners .cf-layout { height: 100%; }
.cf-cert-corners .cf-top-row, .cf-cert-corners .cf-foot-row { height: 1px; }
.cf-cert-corners .cf-brand, .cf-cert-corners .cf-foot { width: auto; margin: 0 auto; }
.cf-cert-corners .cf-logo-cell { padding: 0 10px; }
html body .print-format .cf-cert-corners img.cf-logo { height: 34px !important; }
.cf-cert-corners .cf-site { font-size: 18px; }
.cf-cert-corners .cf-heading-row { width: 560px; margin: 28px auto 0; }
.cf-cert-corners .cf-heading { font-size: 16px; letter-spacing: 0.06em; padding: 0 16px; white-space: nowrap; width: 1px; }
.cf-cert-corners[dir="rtl"] .cf-heading { letter-spacing: normal; }
.cf-cert-corners .cf-line { height: 1px; background: #7c7c7c; }
.cf-cert-corners .cf-name { line-height: 1.12; max-width: 880px; margin: 0 auto; }
.cf-cert-corners .cf-verb { font-size: 18px; margin-top: 24px; }
.cf-cert-corners .cf-title { line-height: 1.25; margin: 8px auto 0; max-width: 800px; }
.cf-cert-corners .cf-people { font-size: 16px; margin: 18px auto 0; max-width: 760px; line-height: 1.4; }
.cf-cert-corners .cf-foot { font-size: 13px; color: #525252; text-align: left; }
.cf-cert-corners[dir="rtl"] .cf-foot { text-align: right; }
.cf-cert-corners .cf-meta { padding: 0 14px; white-space: nowrap; }
.cf-cert-corners .cf-verify-cell { white-space: normal; max-width: 260px; }
.cf-cert-corners .cf-ink { color: #171717; font-size: 15px; }
.cf-cert-corners .cf-qr-cell { width: 64px; padding: 0 14px; }
html body .print-format .cf-cert-corners img.cf-qr { width: 64px !important; height: 64px !important; }
